import math

def lse2(a, b): return math.log(math.exp(a) + math.exp(b))
def softmax2(a, b):
    ea, eb = math.exp(a), math.exp(b); return ea/(ea+eb)
def d(f, x, h=1e-6): return (f(x+h)-f(x-h))/(2*h)
def d2(f, x, h=1e-4): return (f(x+h)-2*f(x)+f(x-h))/h/h

L2 = math.log(2); b = 0.4
for a in (-1.0, 0.7, 2.3):
    assert abs(d(lambda x: lse2(x, b), a) - softmax2(a, b)) < 1e-5
    p = softmax2(a, b)
    assert abs(d2(lambda x: lse2(x, b), a) - p*(1-p)) < 1e-3
for a, c in [(0,0),(3,1),(10,9.5)]:
    assert max(a,c) - 1e-9 <= lse2(a,c) <= max(a,c) + L2 + 1e-9
assert abs(lse2(2,2) - (2 + L2)) < 1e-12
print('free-energy calculus: gradient=prob, curvature=variance verified')

