function STABLE_SOFTMAX(w[1..n]):
    m <- max(w)                      # legitimate by shift invariance
    for i in 1..n: e[i] <- exp(w[i] - m)
    Z <- sum(e)                      # Z > 0 since e[i] > 0
    for i in 1..n: p[i] <- e[i] / Z
    return p                         # sum(p) = 1, p[i] > 0
